"""Own one disposable home across two explicitly contained Linux service instances.

This diagnostic uses installed product APIs. It never changes HOME, publisher
deadlines, service capacity or native authority selection. Initial construction
and compilation precede the observer and cannot provide startup SLO evidence.
"""

from __future__ import annotations

import copy
import os
import shutil
import stat
import sys
import tempfile
import threading
import time
from pathlib import Path
from typing import Any

from scripts.native_slo_command_fixture import prepare_empty_command_authority
from scripts.native_slo_contract import MAX_READINESS_P95_MS
from scripts.native_slo_expiry import _authenticated_readback, _readback_matches
from scripts.native_slo_failure import failure_evidence
from scripts.native_slo_mixed_witness import writer_drained
from scripts.native_slo_session import stop_native_resident
from scripts.native_slo_workloads import configuration_text
from scripts.native_slo_workspace_observer import public_binding

COUNTS = (1, 10, 100)
MAX_RETAINED_THREADS = 512


def diagnostic_failure(error: BaseException) -> dict[str, object]:
    if isinstance(error, Exception):
        return failure_evidence(error)
    return {"type": type(error).__name__, "base_exception": True}


def private_identity(path: Path) -> dict[str, int]:
    info = path.lstat()
    assert path.resolve(strict=True) == path and not path.is_symlink()
    assert stat.S_ISDIR(info.st_mode) and info.st_uid == os.getuid()
    assert stat.S_IMODE(info.st_mode) == 0o700
    return {"device": info.st_dev, "inode": info.st_ino, "uid": info.st_uid, "mode": stat.S_IMODE(info.st_mode)}


def thread_owners(daemon: Any, publisher: Any) -> list[tuple[str, Any]]:
    server = daemon._server
    result = [("service", daemon), ("http", server), ("publisher", publisher)]
    for label, owner, name in (
        ("writer", server, "runtime_hook_evidence_writer"),
        ("runner", server, "hook_process_runner"),
        ("heartbeat", server, "runtime_heartbeat"),
        ("attention", server, "approval_attention"),
        ("general", server, "general_request_executor"),
        ("control", server, "control_request_executor"),
        ("diagnostics", daemon, "_diagnostics"),
        ("command_queue", daemon, "_command_queue_worker"),
        ("cloud_review", daemon, "_cloud_review_sync_worker"),
    ):
        value = getattr(owner, name, None)
        if value is not None:
            result.append((label, value))
    return result


def retain_threads(owners: list[tuple[str, Any]], previous: dict[int, tuple[str, threading.Thread]]) -> None:
    for label, owner in owners:
        if label == "runner":
            with owner._state_lock:
                attributes = {name: tuple(value) if isinstance(value, (tuple, list, set, frozenset)) else value
                              for name, value in vars(owner).items()}
        else:
            attributes = vars(owner).copy()
        for attribute, value in attributes.items():
            values = value if isinstance(value, (tuple, list, set, frozenset)) else (value,)
            for item in tuple(values):
                if isinstance(item, threading.Thread):
                    previous.setdefault(id(item), (label + "." + attribute, item))
                    if len(previous) > MAX_RETAINED_THREADS:
                        raise RuntimeError("owned thread observation exceeded the fixed bound")


class PersistentWorkspaceHome:
    """Keep one private root until every constructed service is contained."""

    def __init__(self, runtime: Path, count: int) -> None:
        from codex_plugin_scanner.guard.native_runtime import native_runtime_status

        if sys.platform != "linux" or type(count) is not int or count not in COUNTS:
            raise ValueError("poststart fixture requires a declared Linux workspace count")
        status = native_runtime_status()
        if (status.mode != "auto" or not status.available or not status.compatible
                or status.reason != "native_ready" or status.identity is None
                or status.identity.path.resolve(strict=True) != runtime.resolve(strict=True)):
            raise RuntimeError("poststart fixture requires the actual installed native authority")
        self.runtime = runtime.resolve(strict=True)
        self.root = Path(tempfile.mkdtemp(prefix="hol-guard-workspace-poststart-")).resolve(strict=True)
        self.guard_home = self.root / ".hol-guard"
        self.guard_home.mkdir(mode=0o700)
        self.workspaces = tuple(self.root / ("workspace-" + str(index)) for index in range(count))
        for workspace in self.workspaces:
            workspace.mkdir(mode=0o700)
        assert self.root.parent == Path(tempfile.gettempdir()).resolve(strict=True)
        assert not self.root.is_relative_to(Path.home().resolve(strict=True))
        self.root_identity = private_identity(self.root)
        self.guard_identity = private_identity(self.guard_home)
        (self.guard_home / "config.toml").write_text(configuration_text("normal"), encoding="utf-8")
        self.instances: list[PostStartService] = []
        self.construction_failed = False
        self.construction_stage = "not_offered"
        self.construction_failure: dict[str, object] | None = None
        self.removed = False
        self.command_authority_prepared = False

    def start_instance(self) -> PostStartService:
        if self.removed or self.construction_failed or len(self.instances) >= 2:
            raise RuntimeError("same-home service construction is no longer admitted")
        if self.instances and self.instances[-1].retirement.get("passed") is not True:
            raise RuntimeError("previous same-home service retirement is not verified")
        assert private_identity(self.root) == self.root_identity
        assert private_identity(self.guard_home) == self.guard_identity
        try:
            instance = PostStartService(self)
        except BaseException as error:
            self.construction_failed = True
            self.construction_failure = {
                "stage": self.construction_stage, "failure": diagnostic_failure(error),
                "partial_service_containment_unproven": self.construction_stage == "service",
            }
            raise
        self.instances.append(instance)
        if len(self.instances) == 2 and instance.publisher is self.instances[0].publisher:
            raise RuntimeError("replacement reused the previous publisher object")
        return instance

    def finish(self) -> dict[str, object]:
        if self.instances and not self.instances[-1].stop_called:
            self.instances[-1].stop()
        contained = not self.construction_failed and all(
            instance.retirement.get("passed") is True for instance in self.instances
        )
        result = {
            "contained": contained,
            "constructed_instances": len(self.instances),
            "construction_failure": self.construction_failure,
            "same_root_identity_preserved": private_identity(self.root) == self.root_identity,
            "same_guard_home_identity_preserved": private_identity(self.guard_home) == self.guard_identity,
            "instance_retirements": [instance.retirement for instance in self.instances],
            "root_removed": False,
            "qualification_complete": False,
        }
        if contained:
            shutil.rmtree(self.root)
            self.removed = True
            result["root_removed"] = True
        return result


class PostStartService:
    """One real service, with one explicit stop and retained first failures."""

    def __init__(self, owner: PersistentWorkspaceHome) -> None:
        from codex_plugin_scanner.guard.daemon.server import GuardDaemonServer
        from codex_plugin_scanner.guard.store import GuardStore

        self.owner = owner
        self.root, self.guard_home, self.runtime = owner.root, owner.guard_home, owner.runtime
        self.workspaces = owner.workspaces
        self.workspace = self.workspaces[-1]
        self.stop_called = False
        self.retirement: dict[str, object] = {"passed": False, "status": "not_stopped"}
        self.construction_stage = owner.construction_stage = "store"
        self.store = GuardStore(self.guard_home)
        if not owner.command_authority_prepared:
            prepare_empty_command_authority(self.store)
            owner.command_authority_prepared = True
        self.construction_stage = owner.construction_stage = "service"
        self.daemon = GuardDaemonServer(self.store, host="127.0.0.1", port=0, home_dir=self.root)
        self.worker = self.daemon._server.hook_worker
        self.publisher = self.worker.policy_snapshot_publisher
        self.threads: dict[int, tuple[str, threading.Thread]] = {}
        self.owned_processes: dict[int, Any] = {}
        self.ready_report: dict[str, object] = {}
        self.construction_stage = owner.construction_stage = "constructed"

    def ready(self) -> dict[str, object]:
        self.daemon.start()
        if self.worker.test_oracle is not None:
            raise RuntimeError("poststart fixture refuses a Python decision oracle")
        deadline = time.monotonic() + MAX_READINESS_P95_MS / 1000
        while True:
            prepared = self.worker.prepare_workspace_policy(None, deadline=deadline)
            snapshot = self.publisher.current_snapshot()
            binding, accepted = _authenticated_readback(self.store)
            if (prepared is not None and snapshot is not None
                    and public_binding(prepared) == public_binding(snapshot)
                    and _readback_matches(binding, accepted, snapshot)
                    and self.daemon._owned_service_ready is True
                    and self.publisher.is_ready() and time.monotonic() <= deadline):
                break
            if time.monotonic() >= deadline:
                raise RuntimeError("poststart global readiness deadline")
            time.sleep(0.005)
        with self.publisher._condition:
            registered = tuple(self.publisher._workspace_paths)
        if registered:
            raise RuntimeError("workspaces were already registered before poststart observation")
        if self.publisher._thread is None or not self.publisher._thread.is_alive():
            raise RuntimeError("ready publisher does not have its actual running thread")
        self.ready_report = {
            "global_ready": True, "owned_service_ready": True,
            "registered_before_explicit_admission": 0,
            "publisher_thread_already_running": True,
            "initial_construction_and_compilation_observed": False,
            "startup_slo_credit": False, "initial_binding": public_binding(snapshot),
            "readiness_gate_ms": MAX_READINESS_P95_MS, "qualification_complete": False,
        }
        self.retain_owned_work()
        return dict(self.ready_report)

    def retain_owned_work(self) -> None:
        retain_threads(thread_owners(self.daemon, self.publisher), self.threads)
        runner = self.daemon._server.hook_process_runner
        with runner._state_lock:
            for slot in runner._all_slots.values():
                self.owned_processes.setdefault(id(slot.process), slot.process)
        if len(self.owned_processes) > 128:
            raise RuntimeError("owned worker process observation exceeded its fixed bound")

    def drain(self) -> dict[str, object]:
        writer = self.daemon._server.runtime_hook_evidence_writer
        deadline = time.monotonic() + 5.0
        while True:
            with writer._condition:
                stats = {**writer.stats(), "in_flight": writer._in_flight}
            if writer_drained(stats):
                self.retain_owned_work()
                return stats
            if time.monotonic() >= deadline:
                raise RuntimeError("original bounded writer drain deadline")
            time.sleep(0.025)

    def stop(self) -> dict[str, object]:
        if self.stop_called:
            return dict(self.retirement)
        self.stop_called = True
        errors, native_stops, failures = [], [], []
        try:
            self.retain_owned_work()
        except BaseException as error:
            errors.append("before_stop_observation:" + type(error).__name__)
            failures.append({"stage": "before_stop_observation", "failure": diagnostic_failure(error)})
        for stage in ("before_service_stop", "after_service_stop"):
            try:
                native = stop_native_resident(self.runtime, self.guard_home, write_diagnostic=False)
                native_stops.append({
                    "stage": stage, "contained": bool(native), "diagnostic": copy.deepcopy(native.diagnostic),
                })
                if not native:
                    errors.append(stage + ":native_containment_failed")
            except BaseException as error:
                native_stops.append({
                    "stage": stage, "contained": False, "error_type": type(error).__name__,
                    "failure": diagnostic_failure(error),
                })
                errors.append(stage + ":" + type(error).__name__)
            if stage == "before_service_stop":
                try:
                    self.daemon.stop()
                except BaseException as error:
                    errors.append("service_stop:" + type(error).__name__)
                    failures.append({"stage": "service_stop", "failure": diagnostic_failure(error)})
        try:
            self.retain_owned_work()
        except BaseException as error:
            errors.append("after_stop_observation:" + type(error).__name__)
            failures.append({"stage": "after_stop_observation", "failure": diagnostic_failure(error)})
        try:
            self.retirement = self.retirement_snapshot(errors, native_stops, failures)
        except BaseException as error:
            errors.append("retirement_observation:" + type(error).__name__)
            failures.append({"stage": "retirement_observation", "failure": diagnostic_failure(error)})
            self.retirement = {
                "passed": False, "status": "observation_incomplete",
                "explicit_service_stop_calls": 1, "native_stop_observations": native_stops,
                "errors": errors, "failures": failures, "qualification_complete": False,
            }
        return dict(self.retirement)

    def retirement_snapshot(
        self, errors: list[str], native_stops: list[dict], failures: list[dict],
    ) -> dict[str, object]:
        server, runner = self.daemon._server, self.daemon._server.hook_process_runner
        writer = server.runtime_hook_evidence_writer
        with runner._state_lock:
            runner_state = {
                "closed": runner._closed, "started": runner._started,
                "slots": len(runner._all_slots), "spawn_threads": len(runner._spawn_threads),
                "retirement_threads": len(runner._retirement_threads),
                "active_reviews": len(runner._active_reviews),
                "supervisor_alive": runner._supervisor_thread is not None and runner._supervisor_thread.is_alive(),
            }
        thread_rows = [
            {"owner_field": label, "alive": thread.is_alive()}
            for label, thread in self.threads.values()
        ]
        process_rows = [
            {"pid": process.pid, "returncode": process.poll(), "reaped": process.poll() is not None}
            for process in self.owned_processes.values()
        ]
        checks = {
            "service_finish_completed": self.daemon._finish_service_completed is True,
            "service_not_quarantined": self.daemon._is_quarantined() is False,
            "service_not_ready": self.daemon._owned_service_ready is False,
            "serve_thread_cleared": self.daemon._thread is None,
            "owner_lock_released": self.daemon._owner_lock is None,
            "publisher_closed": self.publisher.closed is True,
            "publisher_thread_retired": self.publisher._thread is None or not self.publisher._thread.is_alive(),
            "writer_thread_retired": not writer._thread.is_alive(),
            "request_executors_stopped": server.request_executors_stopped is True,
            "no_active_hook_requests": server.active_hook_requests == 0,
            "retained_threads_retired": all(row["alive"] is False for row in thread_rows),
            "retained_direct_workers_reaped": all(row["reaped"] is True for row in process_rows),
            "runner_closed_and_empty": runner_state == {
                "closed": True, "started": False, "slots": 0, "spawn_threads": 0,
                "retirement_threads": 0, "active_reviews": 0, "supervisor_alive": False,
            },
            "same_root_preserved": private_identity(self.root) == self.owner.root_identity,
            "same_guard_home_preserved": private_identity(self.guard_home) == self.owner.guard_identity,
        }
        return {
            "passed": not errors and all(checks.values()), "status": "observed",
            "explicit_service_stop_calls": 1, "native_stop_observations": native_stops,
            "errors": errors, "failures": failures, "checks": checks, "runner": runner_state,
            "last_native_stop_contained": native_stops[-1]["contained"] is True,
            "retained_threads": thread_rows, "retained_direct_workers": process_rows,
            "scope": (
                "Actual service state, owned registries and every retained object; "
                "not a complete escaped-descendant census."
            ),
            "qualification_complete": False,
        }

"""Observe poststart registration, public mutation and one declared last-workspace request."""

from __future__ import annotations

import hashlib
import json
import time
from collections.abc import Mapping
from contextlib import ExitStack, closing
from typing import Any

from scripts.native_slo_contract import MAX_READINESS_P95_MS
from scripts.native_slo_expiry import _authenticated_readback, _readback_matches
from scripts.native_slo_mixed_witness import ReceiptWitness
from scripts.native_slo_workspace_lifecycle_session import diagnostic_failure
from scripts.native_slo_workspace_observer import PublicationObserver, public_binding
from scripts.native_slo_workspace_request_observer import WorkspaceRequestObserver
from scripts.native_slo_workspace_trace import phase_chain

STRICT_OVERLAY = b'sandbox_analysis = "strict"\n# poststart same-home replacement control\n'


def stricter_overlay(home: Any) -> dict[str, object]:
    from codex_plugin_scanner.guard.settings_write_lock import atomic_write_settings

    if len(home.instances) != 1 or home.instances[0].retirement.get("passed") is not True:
        raise RuntimeError("stricter overlay requires verified first-service retirement")
    target = home.workspaces[-1] / ".hol-guard.toml"
    raw = STRICT_OVERLAY
    atomic_write_settings(target, raw.decode("utf-8"))
    if target.read_bytes() != raw:
        raise RuntimeError("stricter overlay did not persist unchanged")
    return {
        "target_workspace_index": len(home.workspaces) - 1,
        "sha256": hashlib.sha256(raw).hexdigest(),
        "bytes": len(raw),
        "written_after_first_service_retirement": True,
        "written_before_replacement_construction_and_registration": True,
        "automatic_workspace_restore_claimed": False,
    }


def ack(session: Any, *, previous: int, action: str, strict: bool, deadline: float) -> Mapping[str, Any]:
    while True:
        prepared = session.worker.prepare_workspace_policy(session.workspace, deadline=deadline)
        snapshot = session.publisher.current_snapshot()
        if isinstance(prepared, Mapping) and isinstance(snapshot, Mapping):
            binding, accepted = _authenticated_readback(session.store)
            effective = snapshot.get("effective_policy")
            if (
                public_binding(snapshot) is not None
                and public_binding(prepared) == public_binding(snapshot)
                and _readback_matches(binding, accepted, snapshot)
                and snapshot["generation"] >= previous
                and snapshot.get("mode") == "enforce"
                and isinstance(effective, Mapping)
                and effective.get("default_action") == action
                and effective.get("subprocess_action") == action
                and (not strict or effective.get("sandbox_analysis") == "strict")
                and time.monotonic() <= deadline
            ):
                return snapshot
        if time.monotonic() >= deadline:
            raise RuntimeError("poststart authenticated acknowledgment deadline")
        time.sleep(0.005)


def observed_chain(observer: Any, index: int, binding: object, accepted: float, deadline: float) -> dict:
    while True:
        result = phase_chain(
            observer.rows(index), binding,
            accepted_ms=(accepted - observer.started) * 1000,
            require_final_compile=False,
        )
        if time.monotonic() >= deadline:
            raise RuntimeError("poststart publication chain deadline")
        if result["matched"] is True:
            return result
        time.sleep(0.005)


class PostStartObservation:
    """Attach only after actual service and global policy readiness."""

    def __init__(self, session: Any, *, instance: int) -> None:
        if type(instance) is not int or instance not in (0, 1):
            raise ValueError("service instance outside the declared pair")
        if session.ready_report.get("global_ready") is not True:
            raise RuntimeError("poststart observation requires actual ready report")
        if session.daemon._owned_service_ready is not True or not session.publisher.is_ready():
            raise RuntimeError("poststart service or publisher readiness was lost")
        self.session = session
        self.instance = instance
        self.publisher_observer = PublicationObserver(session.publisher, session.workspaces)
        self.stack = ExitStack()
        self.phases: list[dict[str, Any]] = []
        self.closed = False
        self.final: dict[str, Any] | None = None

    def __enter__(self) -> PostStartObservation:
        self.stack.enter_context(self.publisher_observer)
        return self

    def __exit__(self, *_args: object) -> None:
        self.close()

    def phase(self, name: str) -> dict[str, object]:
        expected = ("poststart_registration", "public_policy") if self.instance == 0 else ("explicit_reregistration",)
        index = len(self.phases)
        if self.closed or index >= len(expected) or name != expected[index]:
            raise ValueError("poststart phase order invalid")
        observer = self.publisher_observer
        observer.phase(index)
        declared = 0 if name == "poststart_registration" else 1 if name == "public_policy" else 2
        action = "allow" if name == "poststart_registration" else "block"
        strict = self.instance == 1
        result: dict[str, Any] = {
            "name": name, "instance": self.instance, "index": index,
            "registered_workspaces": len(self.session.workspaces),
            "target_workspace_index": len(self.session.workspaces) - 1,
            "secondary_workspace_probed": len(self.session.workspaces) > 1,
            "declared_request_index": declared, "request_offered": False,
            "readiness_deadline_ms": MAX_READINESS_P95_MS,
            "initial_compilation_observed": False,
            "headline_timing_eligible": False, "qualification_complete": False,
            "passed": False, "status": "started", "cleanup_errors": [],
        }
        self.phases.append(result)
        accepted, snapshot, request, witness = None, None, None, None
        try:
            with ExitStack() as stack:
                witness = stack.enter_context(closing(ReceiptWitness(self.session, maximum=3).__enter__()))
                request = stack.enter_context(WorkspaceRequestObserver(
                    self.session, witness, self.session.workspaces, maximum=3,
                ))
                try:
                    before = public_binding(self.session.publisher.current_snapshot_binding())
                    if before is None:
                        raise RuntimeError("poststart phase starting binding is unavailable")
                    minimum_generation = before["generation"] + (1 if name == "public_policy" else 0)
                    started = time.monotonic()
                    registration_returns = []
                    result["explicit_registration_returns"] = registration_returns
                    if name in ("poststart_registration", "explicit_reregistration"):
                        with self.session.publisher._condition:
                            previous_scopes = set(self.session.publisher._workspace_paths)
                        if previous_scopes:
                            raise RuntimeError("workspace scopes appeared before explicit poststart registration")
                        if name == "explicit_reregistration":
                            overlay = (self.session.workspaces[-1] / ".hol-guard.toml").read_bytes()
                            if overlay != STRICT_OVERLAY:
                                raise RuntimeError("stricter overlay changed before explicit reregistration")
                            result["overlay_readback_before_reregistration_sha256"] = (
                                hashlib.sha256(overlay).hexdigest()
                            )
                        for workspace in self.session.workspaces:
                            registration_returns.append(self.session.publisher.register_workspace(workspace))
                        accepted = time.monotonic()
                        if registration_returns != [True] * len(self.session.workspaces):
                            raise RuntimeError("an explicit poststart workspace registration was not accepted")
                        with self.session.publisher._condition:
                            actual_scopes = set(self.session.publisher._workspace_paths)
                        if actual_scopes != set(self.session.workspaces):
                            raise RuntimeError("actual registered workspace set differs")
                    else:
                        from codex_plugin_scanner.guard.config import update_guard_settings

                        update_guard_settings(
                            self.session.guard_home, {"default_action": "block", "subprocess_action": "block"}
                        )
                        accepted = time.monotonic()
                    result.update(
                        operation_ms=(accepted - started) * 1000,
                        accepted_ms=(accepted - observer.started) * 1000,
                    )
                    deadline = accepted + MAX_READINESS_P95_MS / 1000
                    snapshot = ack(
                        self.session, previous=minimum_generation, action=action, strict=strict, deadline=deadline,
                    )
                    acknowledged = time.monotonic()
                    result.update(
                        acknowledgment_observed_ms=(acknowledged - observer.started) * 1000,
                        accept_to_ack_ms=(acknowledged - accepted) * 1000,
                        binding=public_binding(snapshot),
                        stricter_overlay_retained=snapshot["effective_policy"].get("sandbox_analysis") == "strict"
                        if strict else None,
                    )
                    result["publication_chain"] = observed_chain(
                        observer, index, public_binding(snapshot), accepted, deadline,
                    )
                    result["request_offered"] = True
                    request.probe(declared, len(self.session.workspaces) - 1)
                except BaseException as error:
                    result["failure"] = diagnostic_failure(error)
                finally:
                    try:
                        result["writer_drained_before_readback"] = self.session.drain()
                    except BaseException as error:
                        result["cleanup_errors"].append({"stage": "writer_drain", "failure": diagnostic_failure(error)})
                    for stage, operation in (
                        ("request_close", request.close),
                        ("witness_reconcile", lambda: witness.reconcile(verify_all=True)),
                    ):
                        try:
                            operation()
                        except BaseException as error:
                            result["cleanup_errors"].append({"stage": stage, "failure": diagnostic_failure(error)})
                    try:
                        if accepted is not None and snapshot is not None:
                            result["request_receipt_join"] = request.join(
                                accepted=accepted, snapshot=snapshot, action=action, declared_indexes=(declared,),
                            )
                    except BaseException as error:
                        result["cleanup_errors"].append({"stage": "receipt_join", "failure": diagnostic_failure(error)})
                    try:
                        with request._lock:
                            if len(request._rows) > request.maximum:
                                raise RuntimeError("poststart request capture exceeded declared bound")
                            result["complete_request_rows"] = json.loads(
                                json.dumps(list(request._rows.values()), allow_nan=False)
                            )
                            result["owned_offered_attempts"] = list(request._rows)
                        result["complete_witness_report"] = witness.report()
                    except BaseException as error:
                        result["cleanup_errors"].append({
                            "stage": "request_capture", "failure": diagnostic_failure(error),
                        })
        except BaseException as error:
            detail = diagnostic_failure(error)
            if "failure" not in result:
                result["failure"] = detail
            else:
                result["cleanup_errors"].append({"stage": "observer_or_witness_exit", "failure": detail})
        chain, joined = result.get("publication_chain"), result.get("request_receipt_join")
        result.update(
            status="finished",
            passed="failure" not in result and not result["cleanup_errors"]
            and isinstance(chain, Mapping) and chain.get("matched") is True
            and isinstance(joined, Mapping) and joined.get("passed") is True,
        )
        return result

    def close(self) -> dict[str, object]:
        if self.closed:
            assert self.final is not None
            return self.final
        self.closed = True
        self.final = {
            "observer": None, "rows": [], "phases": list(self.phases), "passed": False,
            "capture_errors": [], "qualification_complete": False,
        }
        try:
            self.publisher_observer.freeze()
        except BaseException as error:
            self.final["capture_errors"].append({"stage": "freeze", "failure": diagnostic_failure(error)})
        for name, operation in (
            ("observer", self.publisher_observer.report),
            ("rows", self.publisher_observer.rows),
        ):
            try:
                self.final[name] = operation()
            except BaseException as error:
                self.final["capture_errors"].append({"stage": name, "failure": diagnostic_failure(error)})
        try:
            self.stack.close()
        except BaseException as error:
            self.final["capture_errors"].append({"stage": "close", "failure": diagnostic_failure(error)})
        report = self.final["observer"]
        self.final["passed"] = (
            not self.final["capture_errors"] and isinstance(report, Mapping) and report.get("complete") is True
            and len(self.phases) == (2 if self.instance == 0 else 1)
            and all(row["passed"] is True for row in self.phases)
        )
        return self.final

"""Lossless bounded storage for typed poststart observations and native receipts."""

from __future__ import annotations

import hashlib
import json
import math
import os
import re
from pathlib import Path
from typing import Any

from codex_plugin_scanner.guard.native_decision_receipt import validate_native_decision_receipt
from scripts.native_slo_mixed_load import PrivateLedger
from scripts.native_slo_workspace_lifecycle_session import diagnostic_failure

MAX_PACKET_BYTES = 2 * 1024 * 1024
MAX_PACKETS = 4096
_KEY = re.compile(r"[A-Za-z_][A-Za-z0-9_]{0,95}")
_IDENTIFIER = re.compile(r"[A-Za-z0-9_.:-]{1,512}")
_SENSITIVE = re.compile(r"secret|token|password|private[_-]?key|api[_-]?key", re.IGNORECASE)
_FORBIDDEN_KEYS = frozenset({
    "raw", "payload", "command", "prompt", "path", "cwd", "home", "source",
    "content", "secret", "token", "password", "output", "endpoint", "database",
})
_TEXTS = frozenset({
    "owned Python wrapper endpoints including diagnostic overhead",
    "only the complete declared request set, not all daemon traffic",
    "validated SQLite readback time, not transaction commit time",
    "same-host wall-clock observations at wrapper boundaries",
    "caller-side sequential SQL counts and validated getter, not atomic commit time",
    "Actual service state, owned registries and every retained object; not a complete escaped-descendant census.",
    "poststart registration and same-process service replacement on one owned home",
    "bounded Linux poststart workspace observation",
    "ordered checksummed ASCII JSON packets",
    "full installed sampling and paired baselines",
    "lost metadata hints", "key rotation", "expiry fault", "first admission fault",
    "Python process restart", "matched platform hardware",
})
_STOP_FIELDS = frozenset({
    "acknowledged", "authenticated", "generation_present", "owner_lock",
    "marker_lock", "endpoint", "serving_shutdown",
})
_STOP_VALUES = frozenset({"true", "false", "free", "busy", "unverified", "absent", "present", "verified", "unknown"})


def _stop_diagnostic(value: dict[str, Any]) -> None:
    required = {"schema", "operation", "status"} | _STOP_FIELDS
    if set(value) not in (required, required | {"error"}):
        raise ValueError("poststart native stop diagnostic fields invalid")
    if value["operation"] != "resident-stop" or value["status"] not in {
        "contained", "already-stopped", "failed", "contained_client_cleanup_failed",
    }:
        raise ValueError("poststart native stop diagnostic status invalid")
    if any(value[field] not in _STOP_VALUES for field in _STOP_FIELDS):
        raise ValueError("poststart native stop diagnostic evidence invalid")
    if "error" in value and (
        not isinstance(value["error"], str)
        or re.fullmatch(r"native_resident_stop_[a-z0-9_]{1,128}", value["error"]) is None
    ):
        raise ValueError("poststart native stop diagnostic error invalid")


def _validate(value: Any, depth: int, remaining: list[int]) -> None:
    remaining[0] -= 1
    if remaining[0] < 0 or depth > 24:
        raise ValueError("poststart retained structure outside bound")
    if value is None or type(value) is bool:
        return
    if type(value) is int:
        if value.bit_length() > 256:
            raise ValueError("poststart retained integer outside bound")
        return
    if type(value) is float:
        if not math.isfinite(value):
            raise ValueError("poststart retained clock is not finite")
        return
    if type(value) is str:
        if value not in _TEXTS and (_IDENTIFIER.fullmatch(value) is None or _SENSITIVE.search(value)):
            raise ValueError("poststart retained text is not a declared identifier")
        return
    if type(value) is dict:
        if len(value) > 256:
            raise ValueError("poststart retained mapping outside bound")
        if value.get("schema") == "guard-native-hook-decision-receipt.v1":
            if validate_native_decision_receipt(value) != value:
                raise ValueError("poststart complete receipt identity invalid")
            return
        if value.get("schema") == "hol-guard.native-resident-stop-diagnostic.v1":
            _stop_diagnostic(value)
            return
        for key, child in value.items():
            if type(key) is not str or _KEY.fullmatch(key) is None or key in _FORBIDDEN_KEYS:
                raise ValueError("poststart retained field is not admitted")
            _validate(child, depth + 1, remaining)
        return
    if type(value) in (list, tuple):
        if len(value) > 512:
            raise ValueError("poststart retained sequence outside bound")
        for child in value:
            _validate(child, depth + 1, remaining)
        return
    raise ValueError("poststart retained object has an unsupported type")


def encode_retained(value: Any) -> bytes:
    """Preserve each admitted field and value; never redact or truncate a record."""

    _validate(value, 0, [131072])
    raw = json.dumps(value, ensure_ascii=True, sort_keys=True, separators=(",", ":"), allow_nan=False).encode("ascii")
    if not 0 < len(raw) <= MAX_PACKET_BYTES:
        raise ValueError("poststart retained packet exceeded its fixed bound")
    return raw


def _unique_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("poststart retained JSON has duplicate fields")
        result[key] = value
    return result


def _parse(raw: bytes) -> Any:
    return json.loads(raw, object_pairs_hook=_unique_object)


class RetainedLedger:
    """Preserve full objects through the unchanged 8 KiB underlying row limit."""

    def __init__(self, path: Path) -> None:
        self.path = path
        self.original = PrivateLedger(path)
        identity = os.fstat(self.original._stream.fileno())
        self.identity = (identity.st_dev, identity.st_ino)
        self.expected: list[dict[str, Any]] = []
        self.errors: list[dict[str, Any]] = []
        self.finished = False

    def write(self, value: dict[str, Any]) -> bool:
        if self.finished:
            raise RuntimeError("poststart ledger is already finished")
        if self.errors:
            return False
        try:
            raw = encode_retained(value)
            if len(self.expected) >= MAX_PACKETS:
                raise ValueError("poststart retained packet count exceeded its fixed bound")
            kind = value["kind"]
            if not isinstance(kind, str) or re.fullmatch(r"poststart_[a-z_]{1,64}", kind) is None:
                raise ValueError("poststart retained packet kind invalid")
            chunks = [raw[offset:offset + 2048].decode("ascii") for offset in range(0, len(raw), 2048)]
            record = {
                "schema": "poststart.workspace.packet.v1", "packet": len(self.expected) + 1,
                "packet_kind": kind, "bytes": len(raw),
                "sha256": hashlib.sha256(raw).hexdigest(), "parts": len(chunks),
            }
            self.expected.append(record)
            self.original.write({"kind": "packet_begin", **record})
            for index, chunk in enumerate(chunks, 1):
                self.original.write({"kind": "packet_part", **record, "part": index, "payload": chunk})
            self.original.write({"kind": "packet_end", **record})
            return True
        except BaseException as error:
            self.errors.append({"stage": "write", "type": type(error).__name__, "failure": diagnostic_failure(error)})
            raise

    def _readback(self, original: dict[str, Any]) -> dict[str, int]:
        descriptor = os.open(self.path, os.O_RDONLY | os.O_NOFOLLOW)
        records = size = packet = 0
        digest = hashlib.sha256()
        with os.fdopen(descriptor, "rb") as stream:
            identity = os.fstat(stream.fileno())
            if (identity.st_dev, identity.st_ino) != self.identity or identity.st_size != original["bytes"]:
                raise ValueError("poststart retained file identity changed")

            def row() -> dict[str, Any] | None:
                nonlocal records, size
                raw = stream.readline(8193)
                if not raw:
                    return None
                if not raw.endswith(b"\n") or len(raw) > 8192 or records >= 350000:
                    raise ValueError("poststart retained row incomplete or oversized")
                records += 1
                size += len(raw)
                if size > 256 * 1024 * 1024:
                    raise ValueError("poststart retained file outside bound")
                digest.update(raw)
                value = _parse(raw)
                if not isinstance(value, dict):
                    raise ValueError("poststart retained row is not a mapping")
                return value

            for expected in self.expected:
                if row() != {"kind": "packet_begin", **expected}:
                    raise ValueError("poststart retained packet begin differs")
                chunks = []
                for index in range(1, expected["parts"] + 1):
                    part = row()
                    if part is None or type(part.get("payload")) is not str:
                        raise ValueError("poststart retained packet part is absent")
                    chunk = part.pop("payload")
                    if part != {"kind": "packet_part", **expected, "part": index} or not 0 < len(chunk) <= 2048:
                        raise ValueError("poststart retained packet part differs")
                    chunks.append(chunk)
                if row() != {"kind": "packet_end", **expected}:
                    raise ValueError("poststart retained packet end differs")
                raw = "".join(chunks).encode("ascii")
                value = _parse(raw)
                if len(raw) != expected["bytes"] or hashlib.sha256(raw).hexdigest() != expected["sha256"]:
                    raise ValueError("poststart retained full packet differs")
                if encode_retained(value) != raw or value["kind"] != expected["packet_kind"]:
                    raise ValueError("poststart retained full object differs")
                packet += 1
            if row() is not None:
                raise ValueError("poststart retained ledger has undeclared rows")
        if records != original["records"] or size != original["bytes"] or digest.hexdigest() != original["sha256"]:
            raise ValueError("poststart retained ledger digest differs")
        return {"packets": packet, "records": records, "bytes": size}

    def finish(self) -> dict[str, Any]:
        if self.finished:
            raise RuntimeError("poststart ledger finish repeated")
        self.finished = True
        result: dict[str, Any] = {
            "complete": False, "packets": len(self.expected), "errors": self.errors,
            "complete_object_encoding": "ordered checksummed ASCII JSON packets",
            "underlying_record_limit_bytes": 8192,
        }
        try:
            original = self.original.finish()
            result.update(original)
            result["readback"] = self._readback(original)
            result["complete"] = not self.errors
        except BaseException as error:
            self.errors.append({
                "stage": "finish_or_readback", "type": type(error).__name__, "failure": diagnostic_failure(error),
            })
        return result

"""Bounded Linux poststart workspace and same-home service replacement diagnostic.

Initial compilation is excluded. The two service instances share one Python
process and one owned home. Full typed observations stay in the private ledger;
this diagnostic does not provide installed SLO or platform qualification.
"""

from __future__ import annotations

import argparse
import json
import os
import sys
from pathlib import Path
from typing import Any

if __package__ in {None, ""}:
    sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from scripts.bench_guard_native_installed_slo_runtime import _clear_proof_overrides, _runtime_summary
from scripts.native_slo_workspace_lifecycle_evidence import RetainedLedger, encode_retained
from scripts.native_slo_workspace_lifecycle_observation import PostStartObservation, stricter_overlay
from scripts.native_slo_workspace_lifecycle_session import COUNTS, PersistentWorkspaceHome, diagnostic_failure
from scripts.native_slo_workspace_trace import validate_trace


def service(home: PersistentWorkspaceHome, ordinal: int, ledger: RetainedLedger) -> dict[str, Any]:
    count = len(home.workspaces)
    result: dict[str, Any] = {
        "index": ordinal, "status": "offered", "passed": False, "phase_results": [],
        "qualification_complete": False,
    }
    session = observation = None
    try:
        if not ledger.write({
            "kind": "poststart_service_offer", "registered_workspaces": count, "instance": ordinal,
        }):
            raise RuntimeError("poststart service offer retention unavailable")
        session = home.start_instance()
        result["status"] = "constructed"
        result["ready"] = session.ready()
        result["status"] = "ready"
        phases = ("poststart_registration", "public_policy") if ordinal == 0 else ("explicit_reregistration",)
        observation = PostStartObservation(session, instance=ordinal)
        with observation:
            for name in phases:
                phase: dict[str, Any] = {"name": name, "status": "offered", "passed": False}
                result["phase_results"].append(phase)
                try:
                    if not ledger.write({
                        "kind": "poststart_phase_offer", "registered_workspaces": count,
                        "instance": ordinal, "phase": name,
                    }):
                        raise RuntimeError("poststart phase offer retention unavailable")
                    phase.update(observation.phase(name))
                except BaseException as error:
                    phase.update(status="failed", failure=diagnostic_failure(error))
                finally:
                    ledger.write({
                        "kind": "poststart_phase_terminal", "registered_workspaces": count,
                        "instance": ordinal, "phase": phase,
                    })
                if phase["passed"] is not True:
                    break
        if observation.final is None:
            raise RuntimeError("poststart observer final record is missing")
        for row in observation.final["rows"]:
            ledger.write({
                "kind": "poststart_publisher_event", "registered_workspaces": count,
                "instance": ordinal, "event": row,
            })
        validate_trace(observation.final["rows"], observation.final["observer"])
    except BaseException as error:
        result["failure"] = diagnostic_failure(error)
    finally:
        if observation is not None:
            if observation.final is None:
                try:
                    observation.close()
                except BaseException as error:
                    result["observation_final_failure"] = diagnostic_failure(error)
            result["observation"] = observation.final
        if session is not None:
            try:
                result["retirement"] = session.stop()
            except BaseException as error:
                result["retirement"] = {
                    "passed": False, "status": "stop_observation_incomplete",
                    "retained": session.retirement, "failure": diagnostic_failure(error),
                }
        else:
            result["retirement"] = {"passed": False, "status": "construction_not_complete"}
        result["status"] = "finished"
        result["passed"] = (
            "failure" not in result and "observation_final_failure" not in result
            and observation is not None and observation.final is not None
            and observation.final["passed"] is True and result["retirement"]["passed"] is True
            and not ledger.errors
        )
        try:
            ledger.write({
                "kind": "poststart_service_terminal", "registered_workspaces": count, "instance": result,
            })
        except BaseException as error:
            result.update(passed=False, retention_failure=diagnostic_failure(error))
    return result


def cell(runtime: Path, count: int, ledger: RetainedLedger) -> dict[str, Any]:
    result: dict[str, Any] = {
        "registered_workspaces": count, "passed": False,
        "instances": [], "qualification_complete": False,
        "scope": "poststart registration and same-process service replacement on one owned home",
    }
    home = None
    try:
        if not ledger.write({"kind": "poststart_cell_offer", "registered_workspaces": count}):
            raise RuntimeError("poststart cell offer retention unavailable")
        home = PersistentWorkspaceHome(runtime, count)
        for ordinal in (0, 1):
            if ordinal == 1:
                result["stricter_overlay"] = stricter_overlay(home)
                ledger.write({
                    "kind": "poststart_stricter_overlay", "registered_workspaces": count,
                    **result["stricter_overlay"],
                })
            instance = service(home, ordinal, ledger)
            result["instances"].append(instance)
            if instance["passed"] is not True:
                break
        result["passed"] = len(result["instances"]) == 2 and all(
            row["passed"] is True for row in result["instances"]
        )
    except BaseException as error:
        result.update(passed=False, failure=diagnostic_failure(error))
    finally:
        if home is not None:
            try:
                result["home_cleanup"] = home.finish()
                if result["home_cleanup"]["contained"] is not True:
                    result["passed"] = False
            except BaseException as error:
                result["passed"] = False
                result["home_cleanup_failure"] = diagnostic_failure(error)
        else:
            result["home_cleanup"] = {
                "contained": False, "status": "home_construction_not_complete",
                "root_removal_observed": False,
            }
        result["unoffered_service_instances"] = 2 - len(result["instances"])
        result["unconstructed_service_instances"] = 2 - (len(home.instances) if home is not None else 0)
        try:
            ledger.write({
                "kind": "poststart_cell_terminal", "registered_workspaces": count,
                "passed": result["passed"], "result": result,
            })
        except BaseException as error:
            result.update(passed=False, retention_failure=diagnostic_failure(error))
    return result


def run(runtime: Path, *, raw_file: Path, counts: tuple[int, ...] = COUNTS) -> dict[str, Any]:
    if sys.flags.optimize:
        raise ValueError("poststart diagnostic requires active invariant checks")
    if counts != COUNTS:
        raise ValueError("poststart diagnostic requires the complete ordered 1/10/100 matrix")
    _clear_proof_overrides()
    identity = _runtime_summary(runtime)
    ledger = RetainedLedger(raw_file)
    cells = []
    failure = None
    try:
        ledger.write({
            "kind": "poststart_matrix_offer", "counts": counts,
            "identity": identity, "qualification_complete": False,
        })
        for count in counts:
            observed = cell(runtime, count, ledger)
            cells.append(observed)
            if observed["passed"] is not True or ledger.errors:
                break
    except BaseException as error:
        failure = diagnostic_failure(error)
    finally:
        raw = ledger.finish()
    result = {
        "scope": "bounded Linux poststart workspace observation",
        "identity": identity, "declared_counts": counts,
        "cells": cells, "unvisited_counts": list(counts[len(cells):]),
        "failure": failure, "ledger": raw,
        "implemented_diagnostic_passed": (
            failure is None and raw["complete"] is True
            and len(cells) == len(counts) and all(row["passed"] is True for row in cells)
        ),
        "initial_compilation_observed": False,
        "same_process_service_replacement": True,
        "python_process_restart_tested": False,
        "automatic_workspace_restore_tested": False,
        "headline_timing_eligible": False,
        "qualification_complete": False,
        "pending": [
            "full installed sampling and paired baselines",
            "lost metadata hints", "key rotation", "expiry fault", "first admission fault",
            "Python process restart", "matched platform hardware",
        ],
    }
    encode_retained(result)
    return result


def main() -> int:
    from codex_plugin_scanner.guard.native_runtime import native_runtime_status

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--ledger", required=True, type=Path)
    parser.add_argument("--report", required=True, type=Path)
    args = parser.parse_args()
    _clear_proof_overrides()
    status = native_runtime_status()
    if status.identity is None:
        raise RuntimeError("installed native runtime is unavailable")
    args.ledger.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    try:
        result = run(status.identity.path, raw_file=args.ledger)
    except BaseException as error:
        result = {
            "implemented_diagnostic_passed": False, "qualification_complete": False,
            "failure": diagnostic_failure(error), "complete_report_available": False,
        }
    descriptor = os.open(args.report, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    with os.fdopen(descriptor, "wb") as destination:
        destination.write(encode_retained(result) + b"\n")
        destination.flush()
        os.fsync(destination.fileno())
    print(json.dumps({
        "implemented_diagnostic_passed": result["implemented_diagnostic_passed"],
        "qualification_complete": False,
    }))
    return 0 if result["implemented_diagnostic_passed"] else 1


if __name__ == "__main__":
    raise SystemExit(main())
